package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceHolidaySettingsController;import com.rpb.reservation.workforce.calendar.annual.*;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
@WebMvcTest(WorkforceHolidaySettingsController.class) @Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class}) @ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforceHolidaySettingsLocalRuntimeSecurityTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean PublicHolidayService years;@MockBean StoreRestMonthService months;@MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 @Test void onlyExactReadAndProtectedPutPathsArePermitted()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce";for(String path:List.of("/public-holidays/2026","/public-holiday-templates/2027","/store-rest-months/2026-11"))mvc.perform(get(base+path)).andExpect(status().isOk());mvc.perform(put(base+"/public-holidays/2026").header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());verify(years).save(any(),any(),eq(2026),any());mvc.perform(put(base+"/store-rest-months/2026-11").header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());verify(months).save(any(),any(),eq("2026-11"),any());mvc.perform(put(base+"/public-holiday-templates/2027").header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(delete(base+"/public-holidays/2026")).andExpect(status().isForbidden());}
}
